/**
 * Channel Health for dsh-model-router.
 *
 * One fact, one store. Every channel-health fact the UI shows comes from the
 * `router/channel-health` session projection; there is no second in-memory copy.
 * An in-memory copy cannot survive a config save (Cordis restarts the whole
 * fiber), and it cannot reach the browser at all: a plugin remote needs a
 * Typert contribution generated by the build pipeline, and this plugin is a
 * hand-written factory with no build step — `dsh-typert-loader` skips packages
 * without the generated `./typert` export, and only discovers the host face.
 *
 * What the projection folds is passive observation only: the outcomes of real
 * conversations. It answers "how has this channel actually behaved", never
 * "will it work next time". The cheap half of that second question — is the
 * endpoint up, is the credential valid, is the model advertised — is answered
 * by the Host through DSH's own model discovery, which the browser reaches as
 * an already-classified verdict on this plugin's own Remote face; it writes no
 * session event, so it never reaches this fold.
 *
 * The other half — can the model actually produce a token right now — has no
 * zero-cost answer and no plugin-reachable channel, so it is not implemented
 * here. See the decision note for why.
 *
 * Note: 延迟锚点为何在 step/start、为何让步内退避留在本步成本里 —— 见
 * .agents/notes/implemented/2026-10-17-health-latency-step-anchor.md
 */

import type { SessionEvent } from '@deepseek-ai/dsh-session'
import { z } from 'zod'
import { failureCodeOfStream } from './lineage.ts'
import { capTimeline, MAX_TIMELINE_POINTS } from './timeline.ts'
import { routeKeyOf, routeParts } from './routes.ts'

// The route-key rule lives in ./routes.ts because the browser half builds the
// same key; re-exported here so existing importers keep one path.
export { routeKeyOf }

// The window constant lives in ./timeline.ts because the browser half reads the
// same rule; re-exported here so existing importers keep one path.
export { MAX_TIMELINE_POINTS } from './timeline.ts'

/**
 * `unknown` is deliberately absent: a channel with no record is simply
 * unobserved, and the UI renders that from the record's absence rather than
 * from a status nobody ever writes.
 */
export type ChannelHealthStatus = 'healthy' | 'degraded' | 'unhealthy'

export interface ChannelTimelinePoint {
  time: number
  status: ChannelHealthStatus
  /**
   * This route's cost inside the event's own step: `step/start` (re-anchored by
   * each `request/header`) to this event. Not a turn cost — a tool-loop turn's
   * later steps each carry their own. Not TTFT either — DSH's own
   * `sessionStats` projection owns TTFT.
   */
  latencyMs?: number
  /** Output rate over that step cost, first-token wait included. Not a decode rate. */
  throughputTps?: number
  error?: string
}

export interface ChannelHealthRecord {
  route: string
  provider: string
  model: string
  status: ChannelHealthStatus
  latencyMs?: number
  throughputTps?: number
  lastError?: string
  lastCheckedAt: number
  timeline: ChannelTimelinePoint[]
}

/**
 * The health verdict one failure code carries, or `undefined` when the failure
 * says nothing about the channel.
 *
 * The codes are DSH's own taxonomy, not this plugin's: `AUTH` and `QUOTA` come
 * from `llm/src/error.ts` (`QUOTA_EXCEEDED_CODE`), and `llm-deepseek`'s
 * transport maps 401/403 to `AUTH`. Nothing named `AUTH_FAILED` exists in DSH.
 *
 * RATE_LIMIT is degradation rather than sickness: the route works, it is only
 * throttled right now. AUTH, QUOTA, SERVER, TIMEOUT and TRANSPORT are the
 * channel's own faults. INVALID_REQUEST and EMPTY_RESPONSE are facts about the
 * request, not the route, and ABORTED is the user's own doing — scoring any of
 * those unhealthy would paint a working channel red, which is precisely the
 * kind of silent lie this plugin exists to avoid.
 */
export function classifyHealth(code: string): ChannelHealthStatus | undefined {
  switch (code) {
    case 'RATE_LIMIT': return 'degraded'
    case 'AUTH':
    case 'QUOTA':
    case 'SERVER':
    case 'TIMEOUT':
    case 'TRANSPORT': return 'unhealthy'
    default: return undefined
  }
}

/** Append one timeline point, keeping the window bounded. */
export function pushTimelinePoint(
  existingTimeline: readonly ChannelTimelinePoint[] | undefined,
  point: ChannelTimelinePoint,
): ChannelTimelinePoint[] {
  const current = existingTimeline ? existingTimeline.slice() : []
  current.push(point)
  return capTimeline(current)
}

/**
 * This route's cost inside the event's own step, or `undefined` when the event
 * belongs to no open step.
 *
 * The gate is what makes the number mean one thing: a settlement from another
 * step (a tool-loop turn's later step, or a step the fold never saw open) has
 * no measured cost here, and reporting one would bill it this route's time.
 */
function elapsedSince(
  state: ChannelHealthProjectionState,
  turn: number | undefined,
  step: number | undefined,
  time: number,
): number | undefined {
  const open = state.openStep
  if (open === undefined || open.turn !== turn || open.step !== step) return undefined
  return Math.max(1, time - open.start)
}

// ---------------- Session Projection ----------------

export const CHANNEL_HEALTH_KEY = 'router/channel-health'

const timelinePointSchema = z.object({
  time: z.number(),
  status: z.enum(['healthy', 'degraded', 'unhealthy']),
  latencyMs: z.number().optional(),
  throughputTps: z.number().optional(),
  error: z.string().optional(),
})

const healthRecordSchema = z.object({
  route: z.string(),
  provider: z.string(),
  model: z.string(),
  status: z.enum(['healthy', 'degraded', 'unhealthy']),
  latencyMs: z.number().optional(),
  throughputTps: z.number().optional(),
  lastError: z.string().optional(),
  lastCheckedAt: z.number(),
  timeline: z.array(timelinePointSchema),
})

const projectionStateSchema = z.object({
  records: z.record(z.string(), healthRecordSchema),
  currentRoute: z.string().optional(),
  openStep: z.object({ turn: z.number(), step: z.number(), start: z.number() }).optional(),
}).strict()

interface ChannelHealthProjectionState {
  records: Record<string, ChannelHealthRecord>
  currentRoute?: string
  /**
   * The step whose cost is being measured, and when this route's request
   * inside it started. Anchored on `step/start` (re-anchored by each
   * `request/header`, which names a new request on the route it carries) and
   * gated by `(turn, step)` — DSH's own model-time shape, see the fold below.
   */
  openStep?: { turn: number; step: number; start: number }
}

/**
 * Fold real conversation outcomes into per-route health records.
 *
 * `assistant/attempt` carries no provider or model — only the preceding
 * `request/header` knows the route — so the fold tracks the current route and
 * attributes both the failure and the settlement to it.
 */
export const channelHealthProjection = {
  key: CHANNEL_HEALTH_KEY,
  // v3: the latency anchor moved from a bare `request/header` timestamp to
  // `openStep` (turn, step, start). A persisted v2 row carries `lastStart`,
  // which the strict schema now rejects — so the version bump makes the
  // registry discard those rows, the same way v2 discarded v1's.
  stateVersion: 3,
  stateSchema: projectionStateSchema,
  init: (): ChannelHealthProjectionState => ({ records: {} }),
  apply(state: ChannelHealthProjectionState, event: SessionEvent): ChannelHealthProjectionState {
    switch (event.type) {
      case 'step/start': {
        // The latency anchor lives here, not on `request/header`: a
        // steady-state session emits no header for step 2..N (`requestHeaderLogged`
        // is set once and never reset, agent.ts:635-651), so a header anchor
        // made every later step of a tool-loop turn inherit the whole turn's
        // time — model time plus tool-execution time plus any backoff.
        // DSH's own session-stats projection measures model time the same way
        // (`step/start` → `assistant/message`, gated by (turn, step),
        // session-stats/src/projection.ts:133-149); an in-step `llm/retry`
        // stays inside the step's cost there and stays here.
        const { turn, step } = event.data
        // A step/start that names no step opens nothing: the gate below would
        // otherwise match every later event and measure against a step that
        // was never started.
        if (typeof turn !== 'number' || typeof step !== 'number') return state
        const open = state.openStep
        if (open !== undefined && open.turn === turn && open.step === step) return state
        return { ...state, openStep: { turn, step, start: event.time } }
      }
      case 'request/header': {
        // Boundary: a header without a route names nothing to attribute to.
        const config = event.data.header.config
        if (config === undefined || !config.provider || !config.model) return state
        // A header names a NEW request on the route it carries, so it
        // re-anchors the open step: a failover inside one step must not bill
        // the previous candidate's failure to the route that answered.
        const open = state.openStep
        return {
          ...state,
          currentRoute: routeKeyOf(config.provider, config.model),
          ...open === undefined ? {} : { openStep: { ...open, start: event.time } },
        }
      }
      case 'assistant/attempt': {
        const route = state.currentRoute
        if (route === undefined) return state
        const code = failureCodeOfStream(event.data.stream)
        if (code === undefined) return state
        const status = classifyHealth(code)
        // A failure that says nothing about the channel leaves the record alone.
        if (status === undefined) return state
        const { provider, model } = routeParts(route)
        const existing = state.records[route]
        const latencyMs = elapsedSince(state, event.data.turn, event.data.step, event.time)
        const record: ChannelHealthRecord = {
          route,
          provider,
          model,
          status,
          latencyMs,
          lastError: code,
          lastCheckedAt: event.time,
          timeline: pushTimelinePoint(existing?.timeline, { time: event.time, status, latencyMs, error: code }),
        }
        return { ...state, records: { ...state.records, [route]: record } }
      }
      case 'assistant/message': {
        const route = state.currentRoute
        if (route === undefined) return state
        const { provider, model } = routeParts(route)
        const latencyMs = elapsedSince(state, event.data.turn, event.data.step, event.time)
        // Usage sits beside `message` on the event data, never inside it.
        const outputTokens = event.data.usage?.outputTokens
        const throughputTps = typeof outputTokens === 'number' && latencyMs !== undefined
          ? Math.round((outputTokens / (latencyMs / 1000)) * 10) / 10
          : undefined
        const existing = state.records[route]
        const record: ChannelHealthRecord = {
          route,
          provider,
          model,
          status: 'healthy',
          latencyMs,
          throughputTps: throughputTps ?? existing?.throughputTps,
          lastCheckedAt: event.time,
          timeline: pushTimelinePoint(existing?.timeline, {
            time: event.time,
            status: 'healthy',
            latencyMs,
            throughputTps,
          }),
        }
        return { ...state, records: { ...state.records, [route]: record } }
      }
      default:
        return state
    }
  },
  wire: {
    viewSchema: z.record(z.string(), healthRecordSchema),
    view: (state: ChannelHealthProjectionState) => state.records,
  },
}
